declare module "node:fs" { export function readFileSync(path: string, encoding: "utf8"): string }
declare function setTimeout(handler: () => void, ms?: number): number
declare function clearTimeout(id: number | undefined): void

modules.text:
export function createTimer() {
  let id: ReturnType<typeof setTimeout> | undefined
  return { start: (ms: number) => { id = setTimeout(() => {}, ms) }, stop: () => clearTimeout(id) }
}

export type Timer = ReturnType<typeof createTimer>

import { readFileSync } from "node:fs"

export function load(path: string) {
  return { text: readFileSync(path, "utf8") }
}

export type Loaded = ReturnType<typeof load>
